    75  void ZSTD_free(void* ptr, ZSTD_customMem customMem)
    76  {
    77      if (ptr!=NULL) {
    78          if (customMem.customFree)
    79              customMem.customFree(customMem.opaque, ptr);
    80          else
    81              free(ptr);
    82      }
